/**
 * Which strings inside an answer are file paths — and which of them only look
 * like one. It is the whole difference between a chip that opens a file and a
 * chip that opens nothing, and both mistakes are easy: `and/or` is not a path,
 * `example.com` is a host, `/chat/settings` is a route, and `main.pl:42` is a
 * Perl file rather than a Polish domain precisely *because* of the `:42`.
 *
 * Nothing here touches the filesystem. It answers "does this read as a path",
 * and the host resolves it.
 */

export type FilePathPosition = { path: string; line?: number; column?: number }

const WINDOWS_DRIVE_RE = /^[a-zA-Z]:([/\\]|$)/
const SLASH_PREFIXED_WINDOWS_DRIVE_RE = /^\/[A-Za-z]:[\\/]/
const RELATIVE_PREFIX_RE = /^(~\/|\.{1,2}\/)/
const EXTERNAL_SCHEME_RE = /^([A-Za-z][A-Za-z0-9+.-]*):([\s\S]*)$/
const POSITION_SUFFIX_RE = /:\d+(?::\d+)?$/
const POSITION_SUFFIX_CAPTURE_RE = /:(\d+)(?::(\d+))?$/
const POSITION_HASH_RE = /^#L(\d+)(?:C(\d+))?$/i
const POSITION_ONLY_RE = /^\d+(?::\d+)?$/
const INLINE_CODE_DISQUALIFIER_RE = /[\s`]/
const PATH_SEPARATOR_RE = /[\\/]/
const FILE_EXTENSION_RE = /\.[A-Za-z0-9_-]+$/
const NUMERIC_DOTTED_RE = /^\d+(?:\.\d+)+$/
/** One path, no spaces — segments of word characters, dots, dashes and `@`. */
const PATH_SHAPE_RE = /^(?:[A-Za-z]:)?[\w@.+~-]*(?:[\\/][\w@.+ -]*[\w@.+-])*[\\/]?$/

export function isWindowsAbsolutePath(value: string): boolean {
  return value.startsWith("\\\\") || WINDOWS_DRIVE_RE.test(value)
}

/** Browser URL parsers write `C:/foo` as `/C:/foo` for file URLs. */
export function stripSlashPrefixedWindowsDrive(path: string): string {
  return SLASH_PREFIXED_WINDOWS_DRIVE_RE.test(path) ? path.slice(1) : path
}

/**
 * Standard OS and dev-container roots. Deliberately excludes app-route-ish
 * prefixes like `/app/` or `/chat/`, so an SPA route never reads as a file.
 */
const POSIX_FILE_ROOT_PREFIXES = [
  "/Users/",
  "/home/",
  "/tmp/",
  "/var/",
  "/etc/",
  "/opt/",
  "/mnt/",
  "/Volumes/",
  "/private/",
  "/root/",
  "/usr/",
  "/bin/",
  "/sbin/",
  "/lib/",
  "/lib64/",
  "/srv/",
  "/dev/",
  "/proc/",
  "/sys/",
  "/run/",
  "/boot/",
  "/media/",
  "/workspace/",
  "/workspaces/",
]

/** Extension-less names that are unmistakably files. `Name:digits` is not enough
 *  on its own — it also matches `error:1`, `port:3000` and `TODO:12`. */
const EXTENSIONLESS_FILE_NAMES = new Set([
  "Makefile",
  "makefile",
  "GNUmakefile",
  "Dockerfile",
  "Containerfile",
  "Justfile",
  "justfile",
  "Rakefile",
  "Gemfile",
  "Procfile",
  "Brewfile",
  "Caddyfile",
  "Vagrantfile",
  "Jenkinsfile",
  "Podfile",
  "Fastfile",
  "BUILD",
  "WORKSPACE",
  "LICENSE",
  "LICENCE",
  "COPYING",
  "NOTICE",
  "AUTHORS",
  "CONTRIBUTORS",
  "CHANGELOG",
  "README",
  "CODEOWNERS",
])

/**
 * Dot-files are enumerated rather than matched as "starts with a dot", so a
 * `.length` in an answer stays code.
 */
const DOT_FILE_RE =
  /^\.(env|gitignore|gitattributes|gitmodules|npmrc|nvmrc|editorconfig|dockerignore|babelrc|prettierrc|eslintrc)[\w.-]*$/i

/** `Next.js` and friends are prose about a library, not a JavaScript file. */
const LIBRARY_DOT_JS_RE =
  /^(next|node|nuxt|vue|react|three|d3|socket|express|nest|jquery|chart|video)\.js$/i

const SINGLE_LABEL_HOSTNAMES = new Set(["localhost"])
/** Allowlists rather than "any TLD", so `conf.d/` and `Makefile.in:12` are not hosts. */
const GENERIC_HOSTNAME_TLDS = new Set([
  "com", "net", "org", "io", "dev", "app", "ai", "co", "edu", "gov", "mil",
  "info", "biz", "xyz", "me", "tv", "cc", "gg", "chat", "cloud", "site",
  "online", "tech", "store", "link",
])
/**
 * Country codes that also name file extensions. A `:line` suffix settles it
 * the other way: `main.pl:42` is a file, `example.pl` is a host.
 */
const COUNTRY_HOSTNAME_TLDS = new Set([
  "uk", "de", "fr", "nl", "se", "no", "fi", "dk", "pl", "ch", "at", "be",
  "es", "it", "pt", "eu", "us", "ca", "au", "nz", "jp", "kr", "cn", "br",
  "ru", "mx", "ie", "cz", "tr", "sg", "hk",
])

function looksLikeHostname(segment: string, hasPosition: boolean): boolean {
  if (segment.startsWith(".")) return false
  const lowered = segment.toLowerCase()
  if (SINGLE_LABEL_HOSTNAMES.has(lowered)) return true
  if (NUMERIC_DOTTED_RE.test(segment)) return true
  const labels = lowered.split(".")
  const lastLabel = labels.at(-1)
  if (labels.length < 2 || lastLabel === undefined) return false
  if (GENERIC_HOSTNAME_TLDS.has(lastLabel)) return true
  return !hasPosition && COUNTRY_HOSTNAME_TLDS.has(lastLabel)
}

function basenameOf(path: string): string {
  const trimmed = path.replace(/[/\\]+$/, "")
  if (trimmed.length === 0) return path
  const separator = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"))
  return separator >= 0 ? trimmed.slice(separator + 1) : trimmed
}

/** The last segment of a path, with any trailing separator trimmed off first. */
export function fileBasename(path: string): string {
  return basenameOf(path)
}

function looksLikeNamedFile(basename: string, hasPosition: boolean): boolean {
  if (EXTENSIONLESS_FILE_NAMES.has(basename)) return true
  if (DOT_FILE_RE.test(basename)) return true
  if (LIBRARY_DOT_JS_RE.test(basename)) return false
  if (FILE_EXTENSION_RE.test(basename)) return true
  // A `:line` suffix is the author saying "this is a file", whatever it ends in.
  return hasPosition
}

function looksLikePosixFilesystemPath(path: string, hasPosition: boolean): boolean {
  if (!path.startsWith("/")) return false
  if (POSIX_FILE_ROOT_PREFIXES.some((prefix) => path.startsWith(prefix))) return true
  if (hasPosition) return true
  return looksLikeNamedFile(basenameOf(path), hasPosition)
}

function hasExternalScheme(value: string): boolean {
  if (isWindowsAbsolutePath(value)) return false
  const match = EXTERNAL_SCHEME_RE.exec(value)
  if (!match) return false
  const rest = match[2] ?? ""
  if (rest.startsWith("//")) return true
  // `file.ts:42` matches the scheme shape too — a bare position is not a URL.
  return !POSITION_ONLY_RE.test(rest)
}

function safeDecodeURIComponent(value: string): string {
  try {
    return decodeURIComponent(value)
  } catch {
    return value
  }
}

/**
 * Turns a `file:` URL into a host path. A non-localhost authority becomes a
 * UNC share, which is what it means on Windows.
 */
export function parseFileUrlHref(
  href: string
): { path: string; hash: string } | null {
  try {
    const parsed = new URL(href)
    if (parsed.protocol.toLowerCase() !== "file:") return null
    const uncHostname =
      parsed.hostname.toLowerCase() === "localhost" ? "" : parsed.hostname
    const path = uncHostname
      ? `\\\\${uncHostname}${parsed.pathname.replaceAll("/", "\\")}`
      : parsed.pathname
    if (path.length === 0) return null
    return {
      path: stripSlashPrefixedWindowsDrive(safeDecodeURIComponent(path)),
      hash: parsed.hash,
    }
  } catch {
    return null
  }
}

/** Splits `src/app.ts:42:7` — or a `#L42C7` anchor — into path, line, column. */
export function splitFilePathPosition(path: string, hash = ""): FilePathPosition {
  const suffixMatch = POSITION_SUFFIX_CAPTURE_RE.exec(path)
  const match = suffixMatch ?? POSITION_HASH_RE.exec(hash)
  if (!match?.[1]) return { path }
  const line = Number.parseInt(match[1], 10)
  const column = match[2] === undefined ? undefined : Number.parseInt(match[2], 10)
  return {
    path: suffixMatch ? path.slice(0, -suffixMatch[0].length) : path,
    ...(line > 0 ? { line } : {}),
    ...(column !== undefined && column > 0 ? { column } : {}),
  }
}

export function formatFilePathPosition(position: FilePathPosition): string {
  if (!position.line) return position.path
  return `${position.path}:${position.line}${position.column ? `:${position.column}` : ""}`
}

/**
 * The file an inline-code span names, or null when it reads as ordinary code.
 *
 * The rules, in the order they settle things: a `file:` URL is a path; a
 * Windows absolute path keeps its backslashes and everything else has them
 * normalized; an explicit path shape (`./`, `~/`, `/`, `C:\`) is trusted,
 * except that a POSIX root has to look like a filesystem rather than a route;
 * and a bare relative string has to survive the hostname check and then name
 * something — an extension, a well-known extension-less file, or a `:line`
 * suffix — or be at least three segments deep.
 */
export function inlineCodeFileReference(text: string): FilePathPosition | null {
  const trimmed = text.trim()
  if (trimmed.length === 0 || trimmed.length > 200) return null
  if (INLINE_CODE_DISQUALIFIER_RE.test(trimmed)) return null

  if (trimmed.toLowerCase().startsWith("file:")) {
    const parsed = parseFileUrlHref(trimmed)
    if (!parsed) return null
    const position = splitFilePathPosition(parsed.path, parsed.hash)
    return position.path.length > 0 ? position : null
  }
  if (hasExternalScheme(trimmed)) return null

  const candidate = isWindowsAbsolutePath(trimmed)
    ? trimmed
    : stripSlashPrefixedWindowsDrive(trimmed.replaceAll("\\", "/"))
  const hasPosition = POSITION_SUFFIX_RE.test(candidate)
  const withoutPosition = candidate.replace(POSITION_SUFFIX_RE, "")
  if (withoutPosition.length === 0) return null
  // A UNC share opens on two separators, which no single-path shape allows.
  if (
    !withoutPosition.startsWith("\\\\") &&
    !PATH_SHAPE_RE.test(withoutPosition)
  ) {
    return null
  }

  const explicitShape =
    RELATIVE_PREFIX_RE.test(withoutPosition) ||
    withoutPosition.startsWith("/") ||
    isWindowsAbsolutePath(withoutPosition)

  if (explicitShape) {
    if (
      withoutPosition.startsWith("/") &&
      !isWindowsAbsolutePath(withoutPosition) &&
      !looksLikePosixFilesystemPath(withoutPosition, hasPosition)
    ) {
      return null
    }
    return splitFilePathPosition(candidate)
  }

  const firstSegment = withoutPosition.split(/[\\/]/)[0] ?? withoutPosition
  if (looksLikeHostname(firstSegment, hasPosition)) return null
  if (looksLikeNamedFile(basenameOf(withoutPosition), hasPosition)) {
    return splitFilePathPosition(candidate)
  }
  /* Nothing names a file, so only depth is left: `packages/web/src` reads as a
     directory, `and/or` does not. */
  const segments = withoutPosition.split(/[\\/]/).filter(Boolean)
  return segments.length >= 3 ? splitFilePathPosition(candidate) : null
}

/**
 * The file a markdown link destination names, or null when it is a URL, a
 * route or an anchor. Only a `:line` the author wrote counts as evidence — a
 * `#L12` anchor never turns `/chat/settings` into a file.
 */
export function parseMarkdownFileLink(href: string): FilePathPosition | null {
  const trimmed = href.trim()
  const normalized =
    trimmed.startsWith("<") && trimmed.endsWith(">") ? trimmed.slice(1, -1) : trimmed
  if (
    normalized.length === 0 ||
    normalized.startsWith("#") ||
    normalized.startsWith("//")
  ) {
    return null
  }

  const fileUrl = normalized.toLowerCase().startsWith("file:")
    ? parseFileUrlHref(normalized)
    : null
  let path: string
  let hash: string
  if (fileUrl) {
    path = fileUrl.path
    hash = safeDecodeURIComponent(fileUrl.hash.trim())
  } else {
    const hashIndex = normalized.indexOf("#")
    const withSearch = hashIndex >= 0 ? normalized.slice(0, hashIndex) : normalized
    hash = hashIndex >= 0 ? safeDecodeURIComponent(normalized.slice(hashIndex)) : ""
    const queryIndex = withSearch.indexOf("?")
    const authored = queryIndex >= 0 ? withSearch.slice(0, queryIndex) : withSearch
    // A percent-encoded drive colon (`/c%3A/`) only becomes strippable decoded.
    path = stripSlashPrefixedWindowsDrive(safeDecodeURIComponent(authored.trim()))
  }
  if (path.length === 0 || hasExternalScheme(path)) return null

  const hasPosition = POSITION_SUFFIX_RE.test(path)
  const position = splitFilePathPosition(path, hash)
  if (isWindowsAbsolutePath(position.path) || RELATIVE_PREFIX_RE.test(position.path)) {
    return position
  }
  if (position.path.startsWith("/")) {
    return looksLikePosixFilesystemPath(path, hasPosition) ? position : null
  }
  if (EXTENSIONLESS_FILE_NAMES.has(position.path)) return position
  if (!PATH_SEPARATOR_RE.test(position.path) && !hasPosition) {
    return FILE_EXTENSION_RE.test(position.path) &&
      !LIBRARY_DOT_JS_RE.test(position.path)
      ? position
      : null
  }
  return looksLikeNamedFile(basenameOf(position.path), hasPosition) ||
    position.path.split(/[\\/]/).filter(Boolean).length >= 3
    ? position
    : null
}

// Adapted from T3 Code (github.com/pingdotgg/t3code), MIT License, (c) 2026 T3 Tools Inc.
/**
 * Turns a DOM selection inside rendered markdown back into markdown source, so
 * highlight-and-copy out of an answer keeps its links, emphasis, lists, fences
 * and tables instead of flattening to a wall of plain text. The `text/plain`
 * flavour carries the markdown; `text/html` carries a sanitized copy of the
 * rendered fragment for rich-paste targets.
 *
 * Nothing here reads React state — it walks the DOM the renderer produced, so
 * it costs nothing until someone actually copies.
 */

const SKIPPED_TAGS = new Set(["BUTTON", "INPUT", "SCRIPT", "STYLE", "TEMPLATE"])
const SKIPPED_CLASS_NAMES = ["select-none", "sr-only"]
/** Chrome the renderer draws — a copy button, an icon — never content. */
const SANITIZED_HTML_SELECTOR = [
  "button",
  "input",
  "script",
  "style",
  "svg",
  '[aria-hidden="true"]',
  ...SKIPPED_CLASS_NAMES.map((className) => `.${className}`),
].join(", ")

/**
 * An element carrying this attribute contributes its value as markdown and
 * nothing else, whatever its tag. It is how a control that renders as a
 * `<button>` — a file-path chip — still copies as the path it names.
 */
const MARKDOWN_COPY_ATTRIBUTE = "data-markdown-copy"

export type MarkdownClipboardPayload = { text: string; html: string }

function isSkippedElement(element: Element): boolean {
  if (SKIPPED_TAGS.has(element.tagName) || element.localName === "svg") return true
  if (element.getAttribute("aria-hidden") === "true") return true
  return SKIPPED_CLASS_NAMES.some((name) => element.classList.contains(name))
}

/** Hoists surrounding whitespace outside the markers: "` bold `" → " **bold** ". */
function wrapInlineMarker(content: string, marker: string): string {
  const match = /^(\s*)([\s\S]*?)(\s*)$/.exec(content)
  const core = match?.[2] ?? ""
  if (!core) return content
  return `${match?.[1] ?? ""}${marker}${core}${marker}${match?.[3] ?? ""}`
}

/**
 * A `code` element whose `pre` wrapper fell outside the copied range is still
 * block code, recognizable by its highlighter line spans or its newlines.
 * Wrapping it like inline code produces backtick-surrounded shell commands on
 * paste.
 */
function isBlockCodeElement(element: Element, content: string): boolean {
  if (content.includes("\n")) return true
  for (const child of element.childNodes) {
    if (
      child.nodeType === Node.ELEMENT_NODE &&
      (child as Element).classList.contains("line")
    ) {
      return true
    }
  }
  return false
}

function wrapInlineCode(code: string): string {
  const longestRun = [...(code.match(/`+/g) ?? [])].reduce(
    (max, run) => Math.max(max, run.length),
    0
  )
  const fence = "`".repeat(Math.max(1, longestRun + (longestRun > 0 ? 1 : 0)))
  const pad = code.startsWith("`") || code.endsWith("`") ? " " : ""
  return `${fence}${pad}${code}${pad}${fence}`
}

function codeFenceFor(code: string): string {
  const longestRun = [...(code.match(/`{3,}/g) ?? [])].reduce(
    (max, run) => Math.max(max, run.length),
    0
  )
  return "`".repeat(Math.max(3, longestRun + 1))
}

function resolveCodeBlockLanguage(pre: Element): string | null {
  const declared =
    pre.closest("[data-language]")?.getAttribute("data-language") ??
    /(?:^|\s)language-(\S+)/.exec(pre.querySelector("code")?.className ?? "")?.[1] ??
    null
  return declared && declared !== "text" ? declared : null
}

function serializeCodeBlock(pre: Element): string {
  const code = (pre.textContent ?? "").replace(/\n$/, "")
  const fence = codeFenceFor(code)
  return `${fence}${resolveCodeBlockLanguage(pre) ?? ""}\n${code}\n${fence}\n\n`
}

function serializeTableCell(cell: Element): string {
  return serializeChildren(cell).replace(/\n+/g, " ").trim().replaceAll("|", "\\|")
}

function tableSeparatorFor(headerCells: Element[]): string {
  const markers = headerCells.map((cell) => {
    const align =
      (cell as HTMLElement).style?.textAlign ?? cell.getAttribute("align") ?? ""
    if (align === "center") return ":---:"
    if (align === "right") return "---:"
    return "---"
  })
  return `| ${markers.join(" | ")} |`
}

function tableRows(table: Element): Element[] {
  return [
    ...table.querySelectorAll(":scope > thead > tr, :scope > tbody > tr, :scope > tr"),
  ]
}

function rowCells(row: Element): Element[] {
  return [...row.children].filter(
    (cell) => cell.tagName === "TH" || cell.tagName === "TD"
  )
}

function serializeTable(table: Element): string {
  const rows = tableRows(table)
  if (rows.length === 0) return ""
  const lines: string[] = []
  let emittedSeparator = false
  for (const row of rows) {
    const cells = rowCells(row)
    if (cells.length === 0) continue
    lines.push(`| ${cells.map((cell) => serializeTableCell(cell)).join(" | ")} |`)
    if (!emittedSeparator) {
      lines.push(tableSeparatorFor(cells))
      emittedSeparator = true
    }
  }
  return `${lines.join("\n")}\n\n`
}

function serializeListItem(item: Element, ordered: boolean, index: number): string {
  const checkbox = item.querySelector('input[type="checkbox"]')
  const task = checkbox
    ? `[${(checkbox as HTMLInputElement).checked ? "x" : " "}] `
    : ""
  const marker = ordered ? `${index}. ${task}` : `- ${task}`
  let content = serializeChildren(item).replace(/\n{3,}/g, "\n\n").trim()
  // Tight list items (no paragraph children) keep nested lists on adjacent lines.
  if (!item.querySelector(":scope > p")) content = content.replace(/\n{2,}/g, "\n")
  const continuationIndent = " ".repeat(marker.length)
  const [first = "", ...rest] = content.split("\n")
  return [
    `${marker}${first}`,
    ...rest.map((line) => (line.length > 0 ? `${continuationIndent}${line}` : line)),
  ].join("\n")
}

function serializeList(list: Element, ordered: boolean): string {
  const start = Number.parseInt(list.getAttribute("start") ?? "1", 10) || 1
  const items = [...list.children].filter((child) => child.tagName === "LI")
  if (items.length === 0) return ""
  const lines = items.map((item, index) =>
    serializeListItem(item, ordered, start + index)
  )
  return `${lines.join("\n")}\n\n`
}

function serializeBlockquote(quote: Element): string {
  const alert = quote.getAttribute("data-alert")
  const content = serializeChildren(quote).replace(/\n{3,}/g, "\n\n").trim()
  if (!content) return ""
  const body = alert ? `[!${alert.toUpperCase()}]\n${content}` : content
  const quoted = body
    .split("\n")
    .map((line) => (line.length > 0 ? `> ${line}` : ">"))
    .join("\n")
  return `${quoted}\n\n`
}

function serializeAnchor(anchor: Element): string {
  const content = serializeChildren(anchor)
  const href = anchor.getAttribute("href") ?? ""
  if (!/^https?:\/\//i.test(href)) return content
  const label = content.trim()
  if (!label) return ""
  if (label === href) return href
  return `[${label}](${href})`
}

function serializeChildren(node: Node): string {
  let out = ""
  for (const child of node.childNodes) out += serializeNode(child)
  return out
}

function serializeNode(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.textContent ?? ""
    // Inter-block formatting whitespace from the renderer collapses to a
    // newline; real inline whitespace passes through untouched.
    if (text.includes("\n") && text.trim().length === 0) return "\n"
    return text
  }
  if (node.nodeType !== Node.ELEMENT_NODE) return ""
  const element = node as Element
  const markdownCopy = element.getAttribute(MARKDOWN_COPY_ATTRIBUTE)
  if (markdownCopy !== null) return markdownCopy
  if (isSkippedElement(element)) return ""

  const headingLevel = /^H([1-6])$/.exec(element.tagName)?.[1]
  if (headingLevel) {
    return `${"#".repeat(Number(headingLevel))} ${serializeChildren(element).trim()}\n\n`
  }

  switch (element.tagName) {
    case "BR":
      return "\n"
    case "HR":
      return "---\n\n"
    case "P":
      return `${serializeChildren(element).trim()}\n\n`
    case "PRE":
      return serializeCodeBlock(element)
    case "CODE": {
      const content = element.textContent ?? ""
      return isBlockCodeElement(element, content) ? content : wrapInlineCode(content)
    }
    case "STRONG":
    case "B":
      return wrapInlineMarker(serializeChildren(element), "**")
    case "EM":
    case "I":
      return wrapInlineMarker(serializeChildren(element), "*")
    case "DEL":
    case "S":
      return wrapInlineMarker(serializeChildren(element), "~~")
    case "A":
      return serializeAnchor(element)
    case "IMG": {
      const alt = element.getAttribute("alt") ?? ""
      const src = element.getAttribute("src") ?? ""
      return alt && src ? `![${alt}](${src})` : ""
    }
    case "UL":
      return serializeList(element, false)
    case "OL":
      return serializeList(element, true)
    case "BLOCKQUOTE":
      return serializeBlockquote(element)
    case "TABLE":
      return serializeTable(element)
    case "DIV":
    case "SECTION":
    case "ARTICLE": {
      const content = serializeChildren(element)
      return content && !content.endsWith("\n") ? `${content}\n` : content
    }
    default:
      return serializeChildren(element)
  }
}

/** Whether a fragment holds one code block and nothing else a reader would see. */
type SoleCodeBlockScan = { pre: Element | null; other: boolean }

function scanForSoleCodeBlock(node: Node, scan: SoleCodeBlockScan): void {
  for (const child of node.childNodes) {
    if (scan.other) return
    if (child.nodeType === Node.TEXT_NODE) {
      if ((child.textContent ?? "").trim().length > 0) scan.other = true
      continue
    }
    if (child.nodeType !== Node.ELEMENT_NODE) continue
    const element = child as Element
    /* Mirrors serializeNode's order: an element carrying markdown of its own
       still contributes it even when its tag is otherwise skipped, as a file
       chip rendered as a button does. */
    const markdownCopy = element.getAttribute(MARKDOWN_COPY_ATTRIBUTE)
    if (markdownCopy !== null) {
      if (markdownCopy.trim().length > 0) scan.other = true
      continue
    }
    if (isSkippedElement(element)) continue
    if (element.tagName === "PRE") {
      if (scan.pre) scan.other = true
      else scan.pre = element
      continue
    }
    if (element.tagName === "IMG" || element.tagName === "HR") {
      scan.other = true
      continue
    }
    if (element.tagName === "LI") {
      /* serializeListItem emits a marker ("- ", "1. ", "[x] ") for every item,
         so an item that does not hold the block carries content of its own even
         when it renders no text. An item that wraps the block is just the
         structure around it, and a pre-only selection would drop the marker. */
      const preBeforeItem = scan.pre
      scanForSoleCodeBlock(element, scan)
      if (!scan.other && scan.pre === preBeforeItem) scan.other = true
      continue
    }
    scanForSoleCodeBlock(element, scan)
  }
}

/**
 * A drag that ends on a block's final newline pulls the closing `pre` into the
 * range, so the fragment holds the whole block even though the reader only
 * highlighted code. Re-fencing that pastes stray backticks, so a fragment whose
 * only visible content is one code block copies as plain code — exactly what a
 * selection that never left the `pre` does.
 */
function soleCodeBlock(container: Node): Element | null {
  const scan: SoleCodeBlockScan = { pre: null, other: false }
  scanForSoleCodeBlock(container, scan)
  return scan.other ? null : scan.pre
}

/** Collapses serializer spacing artifacts without touching fenced content. */
function tidyMarkdown(markdown: string): string {
  return markdown
    .split(/(```[\s\S]*?(?:```|$))/)
    .map((part, index) =>
      index % 2 === 1
        ? part
        : part.replace(/[ \t]+(?=\n)/g, "").replace(/\n{3,}/g, "\n\n")
    )
    .join("")
    .trim()
}

export function serializeRenderedMarkdownFragment(container: Node): string {
  const codeBlock = soleCodeBlock(container)
  if (codeBlock) return (codeBlock.textContent ?? "").replace(/\n$/, "")
  return tidyMarkdown(serializeChildren(container))
}

export function serializeTableElementToMarkdown(table: Element): string {
  return serializeTable(table).trim()
}

function csvCell(value: string): string {
  const normalized = value.replace(/\s+/g, " ").trim()
  return /[",\n]/.test(normalized)
    ? `"${normalized.replaceAll('"', '""')}"`
    : normalized
}

export function serializeTableElementToCsv(table: Element): string {
  const lines: string[] = []
  for (const row of tableRows(table)) {
    const cells = rowCells(row)
    if (cells.length === 0) continue
    lines.push(cells.map((cell) => csvCell(cell.textContent ?? "")).join(","))
  }
  return lines.join("\n")
}

function sanitizedHtmlFrom(container: Element): string {
  for (const node of container.querySelectorAll(SANITIZED_HTML_SELECTOR)) {
    /* A file chip is a button that *is* content. Keep it, and drop only the
       icon and the decorations inside it. */
    if (node.closest("[data-slot='message-file-ref']")) {
      if (node.getAttribute("aria-hidden") === "true" || node.localName === "svg") {
        node.remove()
      }
      continue
    }
    node.remove()
  }
  return `<meta charset="utf-8">${container.innerHTML}`
}

/**
 * Both clipboard flavours for the current selection, or null when it holds
 * nothing worth copying. The caller writes them onto a `copy` event.
 */
export function markdownClipboardPayload(
  selection: Selection
): MarkdownClipboardPayload | null {
  const texts: string[] = []
  const htmls: string[] = []
  for (let index = 0; index < selection.rangeCount; index += 1) {
    const range = selection.getRangeAt(index)
    if (range.collapsed) continue
    const container = document.createElement("div")
    container.appendChild(range.cloneContents())
    const ancestor = range.commonAncestorContainer
    const ancestorElement =
      ancestor.nodeType === Node.ELEMENT_NODE
        ? (ancestor as Element)
        : ancestor.parentElement
    // A selection entirely inside one code block is already exactly what the
    // reader wants — re-serializing it would fence it.
    if (ancestorElement?.closest("pre")) {
      const text = range.toString()
      if (text) {
        texts.push(text)
        htmls.push(sanitizedHtmlFrom(container))
      }
      continue
    }
    const text = serializeRenderedMarkdownFragment(container)
    if (!text) continue
    texts.push(text)
    htmls.push(sanitizedHtmlFrom(container))
  }
  if (texts.length === 0) return null
  return { text: texts.join("\n\n"), html: htmls.join("") }
}

// Adapted from T3 Code (github.com/pingdotgg/t3code), MIT License, (c) 2026 T3 Tools Inc.
/**
 * GitHub's blockquote alerts: a quote whose first line is `[!NOTE]` — or TIP,
 * IMPORTANT, WARNING, CAUTION — renders as a titled callout. They are
 * GitHub's own extension rather than GFM, so remark-gfm leaves the marker as
 * literal text inside the quote. This lifts it off the mdast into a
 * `data-alert` attribute for the blockquote renderer to style, and removes
 * the marker line itself.
 *
 * Only a marker with nothing after it on its own line counts, which is
 * GitHub's rule: `> [!NOTE] aside` is an ordinary quote.
 */

type MarkdownAstNode = {
  type?: string
  value?: unknown
  data?: { hProperties?: Record<string, unknown> }
  children?: MarkdownAstNode[]
}

export const GITHUB_ALERT_KINDS = [
  "note",
  "tip",
  "important",
  "warning",
  "caution",
] as const

export type GithubAlertKind = (typeof GITHUB_ALERT_KINDS)[number]

const GITHUB_ALERT_MARKER = /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\](?:\r?\n|$)/i

function readGithubAlert(node: MarkdownAstNode): void {
  if (node.type !== "blockquote") return
  const paragraph = node.children?.[0]
  const text = paragraph?.children?.[0]
  if (
    paragraph?.type !== "paragraph" ||
    text?.type !== "text" ||
    typeof text.value !== "string"
  ) {
    return
  }
  const match = GITHUB_ALERT_MARKER.exec(text.value)
  if (!match?.[1]) return

  const remainder = text.value.slice(match[0].length)
  /* Whether the marker's own line ended inside this text node. Without it an
     empty remainder is ambiguous: `[!NOTE]\n**bold**` parses as
     [text "[!NOTE]\n", strong] — next-line content in a sibling — while
     `[!NOTE]*aside*` parses the same way minus the newline. */
  const markerEndsItsLine = match[0].endsWith("\n")
  if (remainder.length > 0) {
    // The quote continues on the next line inside the same text node: keep the
    // paragraph, shed the marker line.
    text.value = remainder
  } else if (markerEndsItsLine || paragraph.children?.length === 1) {
    // The marker was the whole text node — a marker-only paragraph, or a marker
    // line whose next line starts as a sibling inline. Drop the node, and the
    // paragraph if it empties.
    paragraph.children?.shift()
    if (paragraph.children?.length === 0) node.children?.shift()
  } else {
    // Something else shares the marker's line — `[!NOTE]*aside*` — which GitHub
    // does not read as an alert.
    return
  }

  node.data = {
    ...node.data,
    hProperties: {
      ...node.data?.hProperties,
      dataAlert: match[1].toLowerCase(),
    },
  }
}

/** remark plugin — hand it to `MessageMarkdown`'s renderer as-is. */
export function remarkGithubAlerts() {
  return (tree: MarkdownAstNode) => {
    const visit = (node: MarkdownAstNode) => {
      node.children?.forEach(visit)
      readGithubAlert(node)
    }
    visit(tree)
  }
}

// Adapted from T3 Code (github.com/pingdotgg/t3code), MIT License, (c) 2026 T3 Tools Inc.
/**
 * CommonMark reads four or more spaces after a list marker as an indented code
 * block. In an agent's output that spacing is almost always accidental
 * alignment — `-       text` — and the reader gets a full code card for every
 * bullet. This re-parses only the blocks that keep excess indentation *and*
 * start on the marker's own line; explicit fences and ordinary indented blocks
 * stay code.
 */

type MarkdownPosition = { start?: { line?: number; offset?: number } }

type MarkdownAstNode = {
  type: string
  value?: unknown
  position?: MarkdownPosition
  children?: MarkdownAstNode[]
}

type MarkdownFile = { value?: unknown }

type MarkdownParser = { parse(markdown: string): unknown }

/** The processor's own parser, re-entered for one recovered chunk. */
type ParseMarkdown = (markdown: string) => unknown

type RecoveredMarkdown = { blocks: MarkdownAstNode[]; source: string }

const INLINE_PARSE_PREFIX = "lc-markdown-inline-prefix:"

function isSameLineOverIndentedCode(
  node: MarkdownAstNode,
  parent: MarkdownAstNode | undefined,
  markdown: string
): boolean {
  if (
    node.type !== "code" ||
    parent?.type !== "listItem" ||
    typeof node.value !== "string" ||
    !/^[\t ]/.test(node.value)
  ) {
    return false
  }

  const nodeStart = node.position?.start
  const parentStart = parent.position?.start
  if (
    nodeStart?.line === undefined ||
    nodeStart.offset === undefined ||
    parentStart?.line === undefined ||
    nodeStart.line !== parentStart.line
  ) {
    return false
  }

  const sourceCharacter = markdown[nodeStart.offset]
  return sourceCharacter !== "`" && sourceCharacter !== "~"
}

function parseRecoveredMarkdown(
  value: string,
  parse: ParseMarkdown
): RecoveredMarkdown {
  /* A text prefix forces block-looking input into a paragraph while keeping the
     processor's own inline extensions (GFM syntax, for one). Later root
     children stay blocks, so blank-line-separated content is never dropped. */
  const source = `${INLINE_PARSE_PREFIX}${value}`
  const document = parse(source) as MarkdownAstNode
  const blocks = document.children
  const paragraph = blocks?.[0]
  const children = paragraph?.type === "paragraph" ? paragraph.children : undefined
  const first = children?.[0]
  if (
    !blocks ||
    !children ||
    first?.type !== "text" ||
    typeof first.value !== "string" ||
    !first.value.startsWith(INLINE_PARSE_PREFIX)
  ) {
    return { blocks: [{ type: "text", value }], source }
  }

  const firstValue = first.value.slice(INLINE_PARSE_PREFIX.length)
  return {
    blocks: [
      {
        ...paragraph,
        type: "paragraph",
        children: [
          ...(firstValue ? [{ ...first, value: firstValue }] : []),
          ...children.slice(1),
        ],
      },
      ...blocks.slice(1),
    ],
    source,
  }
}

function blocksFromIndentedCode(
  node: MarkdownAstNode,
  parse: ParseMarkdown
): RecoveredMarkdown {
  const value = typeof node.value === "string" ? node.value.trim() : ""
  const recovered = parseRecoveredMarkdown(value, parse)
  const first = recovered.blocks[0]
  return {
    ...recovered,
    blocks:
      first && node.position
        ? [{ ...first, position: node.position }, ...recovered.blocks.slice(1)]
        : recovered.blocks,
  }
}

/**
 * remark plugin. It re-enters the processor's own parser for the chunk it
 * recovers — so GFM and every other configured extension still applies — which
 * is why it reads `this` and has to stay a `function`.
 */
export function remarkNormalizeListItemIndentation(this: MarkdownParser) {
  const parse: ParseMarkdown = this.parse.bind(this)
  return (tree: MarkdownAstNode, file: MarkdownFile) => {
    if (typeof file.value !== "string") return
    const markdown = file.value

    const visit = (node: MarkdownAstNode, source: string) => {
      if (!node.children) return
      node.children = node.children.flatMap((child) => {
        if (isSameLineOverIndentedCode(child, node, source)) {
          const recovered = blocksFromIndentedCode(child, parse)
          for (const block of recovered.blocks) visit(block, recovered.source)
          return recovered.blocks
        }
        visit(child, source)
        return [child]
      })
    }

    visit(tree, markdown)
  }
}

